Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info, MagickOffsetType PS_Offset, ssize_t PS_Size, ExceptionInfo *exception) {
  Image
    *clone_image;

  ImageInfo
    *clone_info;

  char
    filename[MaxTextLength];

  FILE
    *file;

  MagickBooleanType
    status;

  size_t
    length;

  ssize_t
    count;

  unsigned char
    *blob;

  clone_info = CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL) {
    (void) ThrowMagickException(exception,GetMagickModule(),ResourceLimitError,"UnableToCloneImageInfo","%s",
      image_info->filename);
    return(image);
  }

  (void) GetPathComponent(image->filename,UniqueFilename,filename);
  file=fopen_utf8(filename,"wb");
  if (file == (FILE *) NULL) {
    (void) CloneImageInfo(&clone_info);
    (void) ThrowMagickException(exception,GetMagickModule(),FileOpenError,"UnableToCreateFile",
      "%s", filename);
    return(image);
  }

  blob = AcquireBlobMemory(PS_Size);
  if (blob == (unsigned char *) NULL) {
    (void) fclose(file);
    (void) RelinquishMagickMemory(blob);
    (void) CloneImageInfo(&clone_info);
    (void) ThrowMagickException(exception,GetMagickModule(),ResourceLimitError,"UnableToAcquireMemory","%s",
      "PS data");
    return(image);
  }

  length = ReadBlob(image,PS_Size,blob);
  if (length != (size_t) PS_Size) {
    (void) fclose(file);
    (void) RelinquishMagickMemory(blob);
    (void) CloneImageInfo(&clone_info);
    (void) ThrowMagickException(exception,GetMagickModule(),CorruptImageError,"UnableToReadPSData",
      "%s", image->filename);
    return(image);
  }

  count = fwrite(blob,1,PS_Size,file);
  (void) fclose(file);
  (void) RelinquishMagickMemory(blob);
  if (count != PS_Size) {
    (void) CloneImageInfo(&clone_info);
    (void) ThrowMagickException(exception,GetMagickModule(),FileWriteError,"UnableToWriteFile",
      "%s", filename);
    return(image);
  }

  clone_image = (Image *) NULL;
  status = ReadImage(clone_info,filename,&clone_image,exception);
  if (status == MagickFalse || clone_image == (Image *) NULL) {
    (void) CloneImageInfo(&clone_info);
    (void) ThrowMagickException(exception,GetMagickModule(),CorruptImageError,"UnableToReadImage",
      "%s", filename);
    return(image);
  }

  clone_image = CloneImage(image,clone_image->columns,clone_image->rows,MagickTrue,exception);
  if (clone_image == (Image *) NULL) {
    (void) CloneImageInfo(&clone_info);
    DestroyImageList(clone_image);
    (void) ThrowMagickException(exception,GetMagickModule(),ResourceLimitError,"UnableToCloneImage",
      "%s", image->filename);
    return(image);
  }

  (void) CloneImageInfo(&clone_info);
  (void) RelinquishMagickMemory(filename);
  (void) RelinquishMagickMemory(blob);
  return(clone_image);
}

Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info,
                                MagickOffsetType PS_Offset, ssize_t PS_Size,
                                ExceptionInfo *exception) {
  Image *new_image = NULL;
  ImageInfo *clone_info = CloneImageInfo(image_info);
  char filename[MaxTextLength];
  FILE *file = NULL;
  MagickBooleanType status;

  if (clone_info == (ImageInfo *) NULL)
    return image;

  (void) GetUniqueFilename(filename);
  file = fopen(filename, "wb");
  if (file == (FILE *) NULL) {
    ThrowFileException(exception, FileOpenError, filename, "ExtractPostscriptImage");
    return image;
  }

  // Write the Postscript data to the temporary file
  if (fwrite((void *) ImageSeekBlob(image, PS_Offset, 0), 1, PS_Size, file) != (size_t) PS_Size) {
    fclose(file);
    (void) RemoveFile(filename);
    return image;
  }

  fclose(file);

  // Check file format using magic number detection
  status = IsPostscriptFilename(filename);
  if (status == MagickFalse) {
    (void) RemoveFile(filename);
    return image;
  }

  // Read the nested image
  new_image = ReadImage(clone_info, filename, exception);
  if (new_image == (Image *) NULL) {
    (void) RemoveFile(filename);
    return image;
  }

  // Replace the current image with the new one
  DestroyImageList(image);
  image = new_image;

  // Clean up
  (void) RemoveFile(filename);

  return image;
}

Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info, MagickOffsetType PS_Offset, ssize_t PS_Size, ExceptionInfo *exception)
{
  ImageInfo *clone_info;
  char filename[MaxTextLength];
  FILE *file;
  Image *new_image;

  clone_info = CloneImageInfo(image_info);
  GetPathComponent(image->filename, Filename, filename);
  AppendToPath(filename, "ps");
  file = fopen(filename, "wb");
  if (file == (FILE *) NULL)
    {
      ThrowFileException(exception, FileOpenError,filename,image_info->filename);
      return(image);
    }

  if (WriteBlobImage(image,PS_Offset,PS_Size,file) == MagickFalse)
    {
      fclose(file);
      return(image);
    }

  fclose(file);

  clone_info = CloneImageInfo(clone_info);
  clone_info->filename = ConstantString(filename);
  new_image = ReadImage(clone_info,exception);
  if (new_image == (Image *) NULL)
    return(image);

  if (image->columns != new_image->columns || image->rows != new_image->rows)
    {
      ReplaceImageContent(image,new_image);
      new_image = DestroyImage(new_image);
    }
  else
    {
      new_image = DestroyImageList(new_image);
      new_image = image;
    }

  return(new_image);
}

Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info, MagickOffsetType PS_Offset, ssize_t PS_Size, ExceptionInfo *exception)
{
  Image
    *clone_image,
    *new_image;

  ImageInfo
    *clone_info;

  MagickBooleanType
    status;

  StringInfo
    *ps_data;

  char
    filename[MagickPathExtent];

  clone_info = CloneImageInfo(image_info);
  if (clone_info == (ImageInfo *) NULL)
    {
      (void) ThrowMagickException(exception, GetMagickModule(), ResourceLimitError, "MemoryAllocationFailed", "Unable to extract Postscript image");
      return image;
    }

  GetPathComponent(image->filename, TailPath, filename, MagickPathExtent);
  (void) FormatLocaleString(filename, MagickPathExtent, "%s-%s", GetMagickTempPrefix(), filename);

  ps_data = AcquireStringInfo((size_t) PS_Size);
  if (ps_data == (StringInfo *) NULL)
    {
      clone_info = DestroyImageInfo(clone_info);
      (void) ThrowMagickException(exception, GetMagickModule(), ResourceLimitError, "MemoryAllocationFailed", "Unable to extract Postscript image");
      return image;
    }

  status = WriteBlobString(ps_data, (const char *) ImageGetBlobStream(image, PS_Offset, (MagickSizeType) PS_Size, exception));
  if (!status)
    {
      ps_data = DestroyStringInfo(ps_data);
      clone_info = DestroyImageInfo(clone_info);
      (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError, "UnableToExtractPostscriptData", "Unable to extract Postscript image");
      return image;
    }

  status = WriteImage(clone_info, ps_data, filename, "ps", exception);
  ps_data = DestroyStringInfo(ps_data);
  clone_info = DestroyImageInfo(clone_info);
  if (!status)
    {
      (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError, "UnableToExtractPostscriptData", "Unable to extract Postscript image");
      return image;
    }

  clone_image = CloneImage(image, 0, 0, MagickTrue, exception);
  if (clone_image == (Image *) NULL)
    {
      (void) ThrowMagickException(exception, GetMagickModule(), ResourceLimitError, "MemoryAllocationFailed", "Unable to extract Postscript image");
      return image;
    }

  clone_image->filename[0] = '\0';
  (void) FormatLocaleString(clone_image->filename, MagickPathExtent, "%s", filename);

  new_image = ReadImage(clone_image->filename, exception);
  if (new_image == (Image *) NULL)
    {
      clone_image = DestroyImage(clone_image);
      (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError, "UnableToExtractPostscriptData", "Unable to extract Postscript image");
      return image;
    }

  (void) CopyImageAttributes(image, new_image);
  (void) CopyImageProfiles(image, new_image);
  (void) CopyImageArtifacts(image, new_image);

  clone_image = DestroyImage(clone_image);

  (void) RemoveFile(filename);

  return new_image;
}

Image *ExtractPostscriptImage(Image *image, const ImageInfo *image_info, MagickOffsetType PS_Offset, ssize_t PS_Size, ExceptionInfo *exception) {
    ImageInfo *clone_info = NULL;
    Image *new_image = NULL;
    char filename[MagickPathExtent];
    FILE *file = NULL;

    if ((PS_Size <= 0) || (PS_Offset < 0))
        return image;

    clone_info = CloneImageInfo(image_info);
    if (GetImageInfoFile(clone_info) != (FILE *) NULL) {
        (void) fclose(GetImageInfoFile(clone_info));
        SetImageInfoFile(clone_info, (FILE *) NULL);
    }

    GetImageInfoFilename(clone_info, filename, MagickPathExtent);
    if ((file = fopen_utf8(filename, "wb")) == (FILE *) NULL)
        return image;

    if (WriteBlobMSBULong(image, PS_Offset) != MagickTrue)
        goto cleanup;

    if (WriteBlobMSBLong(image, PS_Size) != MagickTrue)
        goto cleanup;

    if (WriteBlob(image, PS_Size, image->blob) != MagickTrue)
        goto cleanup;

    (void) fclose(file);
    file = fopen_utf8(filename, "rb");

    if (file == (FILE *) NULL)
        return image;

    clone_info = CloneImageInfo(image_info);
    SetImageInfoFile(clone_info, file);
    new_image = ReadImage(clone_info, exception);
    if (new_image == (Image *) NULL)
        goto cleanup;

    if (image->next != (Image *) NULL) {
        Image *last_image;

        last_image = GetLastImageInList(new_image);
        SetImageList(last_image, image->next);
    }

    DestroyImageList(image);
    return new_image;

cleanup:
    if (file != (FILE *) NULL)
        (void) fclose(file);
    (void) remove_utf8(filename);
    if (clone_info != (ImageInfo *) NULL)
        clone_info = DestroyImageInfo(clone_info);
    if (new_image != (Image *) NULL)
        new_image = DestroyImageList(new_image);
    return image;
}
